"""Render repo-owned Harbor tasks from evals.json and setup_cpu.sh.

SkillEvaluator 1.5.6 preserves native task healthcheck budgets. Its generated
pre_agent_setup checks instead impose a fixed 120-second installation timeout.
Native tasks also retain setup diagnostics and expose failures in Harbor's job
log, which SkillEvaluator includes in its Tier 3 report. ACES supplies the grader.
"""

import argparse
import json
import re
import shlex
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
SETUP_TIMEOUT_SECONDS = 600

# Harbor 0.20 omits healthcheck stdout/stderr from HealthcheckError, but records
# failed collection hooks' output in job.log, even when preflight fails before
# an agent starts. Replay the real setup status here; this hook never grades.
# Keep the excerpt short enough for SkillEvaluator's preflight log tail.
SETUP_DIAGNOSTICS_COMMAND = "bash -c " + shlex.quote(
    """set -euo pipefail
cueq_root="${CUEQ_EVAL_ROOT:-/workspace}"
cueq_status=125
if [ -r "$cueq_root/cueq-setup.status" ]; then
  read -r cueq_status < "$cueq_root/cueq-setup.status" || cueq_status=125
fi
if [[ "$cueq_status" =~ ^[0-9]{1,3}$ ]] && (( 10#$cueq_status <= 255 )); then
  cueq_status=$((10#$cueq_status))
else
  cueq_status=125
fi
if [ "$cueq_status" -eq 0 ]; then
  exit 0
fi
printf 'CUEQ_SETUP_DIAGNOSTICS exit_code=%s (125 means incomplete if no final status was recorded)\\n' "$cueq_status" >&2
if [ -f "$cueq_root/cueq-setup.log" ] && [ -r "$cueq_root/cueq-setup.log" ]; then
  tail -n 12 "$cueq_root/cueq-setup.log" >&2 || printf 'Could not read the setup log.\\n' >&2
else
  printf 'No setup log was produced; setup may have failed before logging started.\\n' >&2
fi
exit "$cueq_status"
"""
)


def task_files(skill_path):
    """Return reproducible native task files, without answers or grader code."""
    skill_path = Path(skill_path)
    evals = skill_path / "evals"
    entries = json.loads((evals / "evals.json").read_text())["evals"]
    setup = (evals / "setup_cpu.sh").read_text()
    # Keep stdout/stderr in a task artifact, including when installation fails.
    # Reset any previous status before starting. Save the setup exit code even
    # through tee; a logging failure must also fail an otherwise successful run.
    command = "bash -c " + shlex.quote(
        "set -euo pipefail\n"
        'cueq_root="${CUEQ_EVAL_ROOT:-/workspace}"\n'
        'printf "125\\n" > "$cueq_root/cueq-setup.status"\n'
        "set +e\n"
        f"bash -lc {shlex.quote(setup)} 2>&1 "
        '| tee "$cueq_root/cueq-setup.log"\n'
        'cueq_codes=("${PIPESTATUS[@]}")\n'
        "set -e\n"
        'cueq_status="${cueq_codes[0]}"\n'
        'if [ "$cueq_status" -eq 0 ]; then cueq_status="${cueq_codes[1]}"; fi\n'
        'printf "%s\\n" "$cueq_status" > "$cueq_root/cueq-setup.status"\n'
        'exit "$cueq_status"\n'
    )
    files = {}
    seen = set()
    for entry in entries:
        case_id = entry["id"]
        if not re.fullmatch(r"[a-zA-Z0-9][a-zA-Z0-9_-]*", case_id):
            raise ValueError(f"Invalid case ID: {case_id!r}")
        if case_id in seen:
            raise ValueError(f"Duplicate case ID: {case_id}")
        seen.add(case_id)
        case = Path(case_id)
        files[case / "instruction.md"] = entry["prompt"] + "\n"
        files[case / "environment/Dockerfile"] = (
            "# The evaluator rebases this image for its selected agent runtime.\n"
            "FROM python:3.11-slim\n"
            "WORKDIR /workspace\n"
        )
        files[
            case / "task.toml"
        ] = f"""# Generated by .github/scripts/prepare_skill_eval_tasks.py; do not edit.
schema_version = "1.3"
artifacts = ["/workspace/cueq-setup.log", "/workspace/cueq-setup.status"]

[task]
name = "nvidia/skillevaluator-{case_id}"
description = "Skill evaluation task for {entry.get("expected_skill") or "none"}"

[metadata]
entry_id = "{case_id}"

[agent]
timeout_sec = 300.0

[verifier]
timeout_sec = 180.0

[[verifier.collect]]
command = {json.dumps(SETUP_DIAGNOSTICS_COMMAND)}
timeout_sec = 10.0

[environment]
cpus = 2
memory_mb = 4096
storage_mb = 2048
workdir = "/workspace"
network_mode = "public"
skills_dir = "/workspace/skills"
build_timeout_sec = 2400.0

[environment.healthcheck]
command = {json.dumps(command)}
interval_sec = 5.0
timeout_sec = {float(SETUP_TIMEOUT_SECONDS)}
retries = 1
"""
    files[Path("dataset.toml")] = (
        "# Generated by .github/scripts/prepare_skill_eval_tasks.py; do not edit.\n"
        '[dataset]\nname = "nvidia/skillevaluator"\n'
        'description = "SkillEvaluator skill evaluation dataset"\n\n'
        + "".join(
            f'[[tasks]]\nname = "nvidia/{case_id}"\n\n' for case_id in sorted(seen)
        )
    )
    return files


def write_tasks(skill_path, *, check=False):
    """Refresh known task files; refuse stale cases rather than deleting them."""
    skill_path = Path(skill_path)
    target = skill_path / "evals/harbor"
    expected = task_files(skill_path)
    expected_cases = {p.parts[0] for p in expected if p.name == "task.toml"}
    existing_cases = {p.parent.name for p in target.glob("*/task.toml")}
    if stale := existing_cases - expected_cases:
        raise ValueError(f"Remove stale native cases explicitly: {sorted(stale)}")
    differing = []
    for relative, content in expected.items():
        path = target / relative
        if path.is_file() and path.read_text() == content:
            continue
        differing.append(str(relative))
        if not check:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(content)
    if check and differing:
        raise ValueError(f"Regenerate native eval tasks: {', '.join(differing)}")
    return target


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "skill",
        type=Path,
        nargs="?",
        default=ROOT / "skills/cuequivariance-torch",
    )
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    print(write_tasks(args.skill, check=args.check))


if __name__ == "__main__":
    main()
